(43261, 'Psalms 46:7', 'Psalms', 46, 7, 'مطلق قادر څښتن دی مل راسره د یعقوب خدای دی پناه ځای زمونږه', 'مطلق قادر چشتن دی مل راسره د یعقوب خدای دی پناه جای زمونزه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_46_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43262, 'Psalms 46:8', 'Psalms', 46, 8, 'راشئ کارونه د څښتن وګورئ وګورئ څنګه هیبتناک کارونه وکړل په دنیا کې هغه', 'راشی کارونه د چشتن وګوری وګوری چنګه هیبتناک کارونه وکرل په دنیا کې هغه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_46_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43263, 'Psalms 46:9', 'Psalms', 46, 9, 'ټوله دنیا کې بندوي جنګونه لیندې له منځه وړي او نېزې ماتوي سېځي سپرونه په سور اور باندې', 'توله دنیا کې بندوی جنګونه لیندې له منجه وری او نېزې ماتوی سېجی سپرونه په سور اور باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_46_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43264, 'Psalms 46:10', 'Psalms', 46, 10, 'څښتن وویل: «جنګ بس کړئ په دې پوه شئ چې زه خدای یم ټولو قومونو څخه لوړ یمه زه ټولې دنیا باندې زه لوړ یمه»', 'چشتن وویل: «جنګ بس کری په دې پوه شی چې زه خدای یم تولو قومونو چخه لور یمه زه تولې دنیا باندې زه لور یمه»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_46_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43265, 'Psalms 46:11', 'Psalms', 46, 11, 'مطلق قادر څښتن دی مل راسره د یعقوب خدای دی پناه ځای زمونږه', 'مطلق قادر چشتن دی مل راسره د یعقوب خدای دی پناه جای زمونزه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_46_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43266, 'Joshua 12:1', 'Joshua', 12, 1, 'مخکې له دې چې موسی مړ شي هغه او د اسراییلو خلکو د اردن د سیند د ختیځې خوا دوو پاچاهانو ته ماتې ورکړه. دې دوو پاچاهانو په هغې سیمې باندې چې د ارنون له درې څخه د حرمون تر غره پورې رسېدله او په هغې کې د اردن د درې ختیځه خوا هم شامله وه، حکومت کاوه.', 'مخکې له دې چې موسی مر شی هغه او د اسراییلو خلکو د اردن د سیند د ختیجې خوا دوو پاچاهانو ته ماتې ورکره. دې دوو پاچاهانو په هغې سیمې باندې چې د ارنون له درې چخه د حرمون تر غره پورې رسېدله او په هغې کې د اردن د درې ختیجه خوا هم شامله وه، حکومت کاوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_12_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43267, 'Joshua 12:2', 'Joshua', 12, 2, 'سیحون د اموریانو پاچا ؤ چې په حشبون کې یې پاچاهي کوله. هغه د عروعیر څخه چې د ارنون د درې په څنګ کې ؤ او د درې له منځ څخه د یبوق تر سیند پورې چې د عمونیانو پوله وه پاچاهي کوله. په دې کې نیم جلعاد شامل ؤ.', 'سیحون د اموریانو پاچا و چې په حشبون کې یې پاچاهی کوله. هغه د عروعیر چخه چې د ارنون د درې په چنګ کې و او د درې له منج چخه د یبوق تر سیند پورې چې د عمونیانو پوله وه پاچاهی کوله. په دې کې نیم جلعاد شامل و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_12_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43268, 'Joshua 12:3', 'Joshua', 12, 3, 'په هغې کې د اردن دره د جلیل د بحیرې څخه جنوب خواته د بیت یشیموت (د مړې بحیرې ختیځ ته) او پیسګاه د غره تر لمنې پورې شامل وو.', 'په هغې کې د اردن دره د جلیل د بحیرې چخه جنوب خواته د بیت یشیموت (د مرې بحیرې ختیج ته) او پیسګاه د غره تر لمنې پورې شامل وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_12_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43269, 'Joshua 12:4', 'Joshua', 12, 4, 'همدارنګه موسی او اسراییلیانو د باشان پاچا عوج ته چې د پاتې شویو رفاییانو څخه ؤ هم ماتې ورکړه. هغه په عشتاروت او ادرعي کې پاچاهي کوله.', 'همدارنګه موسی او اسراییلیانو د باشان پاچا عوج ته چې د پاتې شویو رفاییانو چخه و هم ماتې ورکره. هغه په عشتاروت او ادرعی کې پاچاهی کوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_12_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43270, 'Joshua 12:5', 'Joshua', 12, 5, 'د هغه په پاچاهۍ کې د حرمون غر، سلخه او ټول باشان د جشور او معکې تر پولې او همدارنګه نیم جلعاد د حشبون د پاچا سیحون تر سیمې پورې شامل وو.', 'د هغه په پاچاهی کې د حرمون غر، سلخه او تول باشان د جشور او معکې تر پولې او همدارنګه نیم جلعاد د حشبون د پاچا سیحون تر سیمې پورې شامل وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_12_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43271, 'Joshua 12:6', 'Joshua', 12, 6, 'موسی او د اسراییلو قوم دغو دوو پاچاهانو ته ماتې ورکړه. د څښتن خدمتګار موسی د هغوی خاوره د روبین او جاد قبیلو ته او د منسي نیمې قبیلې ته د هغوی د ملکیت په توګه ورکړه.', 'موسی او د اسراییلو قوم دغو دوو پاچاهانو ته ماتې ورکره. د چشتن خدمتګار موسی د هغوی خاوره د روبین او جاد قبیلو ته او د منسی نیمې قبیلې ته د هغوی د ملکیت په توګه ورکره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_12_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43272, 'Joshua 12:7', 'Joshua', 12, 7, 'یوشع او د اسراییلو قوم هغو پاچاهانو ته چې د اردن د سیند په لوېدیځه خوا کې وو ماتې ورکړه، یعنې د بعل جاد څخه چې د لبنان په دره کې پروت ؤ د حالق تر غره پورې چې په جنوب کې ادوم ته نژدې ؤ. یوشع هغه ځمکه د اسراییلو د قبیلو ترمنځ ووېشله او د ملکیت په توګه یې هغوی ته ورکړه.', 'یوشع او د اسراییلو قوم هغو پاچاهانو ته چې د اردن د سیند په لوېدیجه خوا کې وو ماتې ورکره، یعنې د بعل جاد چخه چې د لبنان په دره کې پروت و د حالق تر غره پورې چې په جنوب کې ادوم ته نژدې و. یوشع هغه جمکه د اسراییلو د قبیلو ترمنج ووېشله او د ملکیت په توګه یې هغوی ته ورکره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_12_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43273, 'Joshua 12:8', 'Joshua', 12, 8, 'کومه ځمکه چې یوشع د هغوی په منځ کې ووېشله په هغې کې دا ځایونه شامل وو: غرنۍ سیمه، د غرونو لوېدیځې لمنې، د اردن دره، د غرونو ختیځ اړخونه او د کنعان جنوبي دښته. دا ځمکه د حیتیانو، اموریانو، کنعانیانو، فرزیانو، حویانو او یبوسیانو وطن ؤ.', 'کومه جمکه چې یوشع د هغوی په منج کې ووېشله په هغې کې دا جایونه شامل وو: غرنی سیمه، د غرونو لوېدیجې لمنې، د اردن دره، د غرونو ختیج ارخونه او د کنعان جنوبی دشته. دا جمکه د حیتیانو، اموریانو، کنعانیانو، فرزیانو، حویانو او یبوسیانو وطن و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_12_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43274, 'Joshua 12:9', 'Joshua', 12, 9, 'د اسراییلو قوم د لاندېنیو ښارونو پاچاهانو ته ماتې ورکړه: اریحا، عای (بیت ییل ته نژدې)،', 'د اسراییلو قوم د لاندېنیو شارونو پاچاهانو ته ماتې ورکره: اریحا، عای (بیت ییل ته نژدې)،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_12_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
